def _local_bd_mobile(raw):
    # Frozen copy of apps.common.utils.phone.local_bd_mobile, so this
    # migration keeps its meaning if that helper ever changes.
    value = re.sub(r"\D", "", raw or "")
    if value.startswith("880"):
        value = value[3:]
    if len(value) == 10 and value.startswith("1"):
        value = f"0{value}"
    return value


def mark_existing_guests(apps, schema_editor):
    """Accounts without an email were only ever created by phone-only guest
    checkout (0020), so they become guest identities. If a race left two for
    one number, the oldest is kept live; the rest are soft-deleted (their
    orders stay attached) so the unique constraint below can be added."""
    User = apps.get_model("accounts", "User")
    kept_phones = set()
    now = timezone.now()
    for user in User.objects.filter(email__isnull=True, deleted_at__isnull=True).order_by(
        "date_joined"
    ):
        user.is_guest = True
        user.phone = _local_bd_mobile(user.phone)
        user.password = make_password(None)
        if user.phone in kept_phones:
            user.deleted_at = now
        kept_phones.add(user.phone)
        user.save(update_fields=["is_guest", "phone", "password", "deleted_at"])


